const INVEST_CATS = ['aplicacao-investimentos', 'resgate-investimentos', 'previdencia', 'reserva-emergencia', 'projetos-vida', 'independencia-financeira'];
const RESERVA_CATS = ['reserva-emergencia','projetos-vida','independencia-financeira','previdencia','aplicacao-investimentos'];
const rows = $input.all().map(i => i.json)
  .filter(r => Object.values(r).some(v => v !== null && v !== undefined));
const trigger = $('When Executed by Another Workflow').item.json;

function formatDate(iso) { const d = new Date(iso); return `${String(d.getUTCDate()).padStart(2,'0')}/${String(d.getUTCMonth()+1).padStart(2,'0')}`; }
function meta(catId) { return CATEGORY_META[catId] || { grupo: 'Outros', emoji: '❔', tipo: 'despesa', nome: catId }; }

let total_entradas = 0, total_saidas = 0, total_aplicado = 0, total_resgatado = 0, total_outras_movimentacoes = 0;

const lancamentos = rows.map(r => {
  const v = Number(r.value);
  const m = meta(r.category_id);
  const isInvest = INVEST_CATS.includes(r.category_id);
  if (isInvest) {
    if (RESERVA_CATS.includes(r.category_id)) total_aplicado += Math.abs(v);
    else if (r.category_id === 'resgate-investimentos') total_resgatado += Math.abs(v);
  } else if (r.type === 'receita') {
    total_entradas += Math.abs(v);
  } else if (r.type === 'despesa') {
    total_saidas += Math.abs(v);
  } else {
    total_outras_movimentacoes += v;
  }
  return {
    date: r.date, data_formatada: formatDate(r.date), category_id: r.category_id,
    categoria_nome: m.nome, emoji: m.emoji, grupo: m.grupo, description: r.description,
    value: v, type: r.type, bank: r.bank, account_name: r.account_name
  };
});

function formatBRL(n) { return Math.abs(Number(n)).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

const total_investido_liquido = Number((total_aplicado - total_resgatado).toFixed(2));

const linhas_totais = [
  `💰 Entradas: **R$ ${formatBRL(total_entradas)}**`,
  `💸 Saídas: **R$ ${formatBRL(total_saidas)}**`
];
if (total_investido_liquido !== 0) {
  linhas_totais.push(`📈 Investido (líquido): **R$ ${formatBRL(total_investido_liquido)}**`);
}
if (Math.abs(total_outras_movimentacoes) > 0.004) {
  const direcao = total_outras_movimentacoes < 0 ? 'saiu' : 'entrou';
  linhas_totais.push(`🔁 Outras movimentações: ${direcao} **R$ ${formatBRL(total_outras_movimentacoes)}**`);
}
const linha_totais = linhas_totais.join('\n');

return [{ json: {
  modo: 'lancamentos',
  periodo: { start_date: trigger.start_date, end_date: trigger.end_date },
  total_entradas: Number(total_entradas.toFixed(2)),
  total_saidas: Number(total_saidas.toFixed(2)),
  total_investido_liquido,
  total_outras_movimentacoes: Number(total_outras_movimentacoes.toFixed(2)),
  linha_totais,
  quantidade: lancamentos.length,
