const diasTotais = Math.max(1, Math.round((dataFim - dataInicio) / 86400000) + 1);
const periodoEmAndamento = hoje >= dataInicio && hoje <= dataFim;
const diasPassadosBruto = Math.round((hoje - dataInicio) / 86400000) + 1;
