    const realizado = Math.abs(Number(r.realizado));
    const ritmo_diario_esperado = planejado > 0 ? Number((planejado / diasTotais).toFixed(2)) : 0;
    const esperado_ate_hoje = Number((ritmo_diario_esperado * diasPassados).toFixed(2));
    const ja_estourou = planejado === 0 ? realizado > 0 : realizado > planejado;
    const acima_do_ritmo = periodoEmAndamento && planejado > 0 && !ja_estourou && realizado > esperado_ate_hoje;
    let mensagem_ritmo = '';
    if (planejado === 0 && realizado > 0) {
      mensagem_ritmo = `🚨 **${m.nome}** não tinha planejamento e teve gasto de **R$ ${formatBRL(realizado)}** neste mês - vale a pena conversar com seu planejador.`;
    } else if (planejado > 0 && realizado > planejado) {
