function montaTexto(lista) {
  const porGrupo = {};
  for (const c of lista) {
    if (!porGrupo[c.grupo]) porGrupo[c.grupo] = [];
    porGrupo[c.grupo].push(c);
  }
  const linhas = [];
  for (const [grupo, itens] of Object.entries(porGrupo)) {
    linhas.push(`**${grupo}**`);
    for (const it of itens) {
      linhas.push(`${it.emoji} **${it.categoria_nome}**: planejado **R$ ${formatBRL(it.planejado)}**`);
