function formatBRL(n) { return Number(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

const rows = $input.all().map(i => i.json);
const trigger = $('When Executed by Another Workflow').item.json;

const compRows = rows.filter(r => r.linha === 'categoria');
const investRow = rows.find(r => r.linha === 'investido') || { total_aplicado: 0, total_resgatado: 0 };

// Ritmo de gasto: compara o quanto ja deveria ter sido gasto ate hoje (media diaria do planejado)
// com o que realmente foi gasto, pra alertar antes do mes acabar.
function paraDataUTC(v) {
  if (v instanceof Date) return new Date(Date.UTC(v.getFullYear(), v.getMonth(), v.getDate()));
  const s = String(v).slice(0, 10);
  const [ano, mes, dia] = s.split('-').map(Number);
  return new Date(Date.UTC(ano, mes - 1, dia));
}
function hojeUTC() {
  const agora = new Date();
  return new Date(Date.UTC(agora.getUTCFullYear(), agora.getUTCMonth(), agora.getUTCDate()));
}
const dataInicio = paraDataUTC(trigger.start_date);
const dataFim = paraDataUTC(trigger.end_date);
const hoje = hojeUTC();
const diasTotais = Math.max(1, Math.round((dataFim - dataInicio) / 86400000) + 1);
const periodoEmAndamento = hoje >= dataInicio && hoje <= dataFim;
const diasPassadosBruto = Math.round((hoje - dataInicio) / 86400000) + 1;
const diasPassados = periodoEmAndamento ? diasPassadosBruto : (hoje > dataFim ? diasTotais : 0);

const categorias = compRows
  .filter(r => meta(r.category_id).tipo !== 'receita' && meta(r.category_id).tipo !== 'investimento')
  .map(r => {
    const m = meta(r.category_id);
    const planejado = Number(r.planejado);
    const realizado = Math.abs(Number(r.realizado));
    const ritmo_diario_esperado = planejado > 0 ? Number((planejado / diasTotais).toFixed(2)) : 0;
    const esperado_ate_hoje = Number((ritmo_diario_esperado * diasPassados).toFixed(2));
    const ja_estourou = planejado === 0 ? realizado > 0 : realizado > planejado;
    const acima_do_ritmo = periodoEmAndamento && planejado > 0 && !ja_estourou && realizado > esperado_ate_hoje;
    let mensagem_ritmo = '';
    if (planejado === 0 && realizado > 0) {
      mensagem_ritmo = `🚨 **${m.nome}** não tinha planejamento e teve gasto de **R$ ${formatBRL(realizado)}** neste mês - vale a pena conversar com seu planejador.`;
    } else if (planejado > 0 && realizado > planejado) {
      const excedente = Number((realizado - planejado).toFixed(2));
      mensagem_ritmo = `🚨 Você já ultrapassou o planejado de **${m.nome}** neste mês (R$ ${formatBRL(excedente)} a mais) - vale a pena conversar com seu planejador.`;
    } else if (acima_do_ritmo) {
      mensagem_ritmo = `🚨 No ritmo atual, você deve estourar o planejado de **${m.nome}** esse mês.`;
    }
    return {
      category_id: r.category_id, categoria_nome: m.nome, grupo: m.grupo, emoji: m.emoji,
      planejado, realizado,
      ritmo_diario_esperado, esperado_ate_hoje, acima_do_ritmo, ja_estourou, mensagem_ritmo
    };
  });

const total_planejado = categorias.reduce((acc, c) => acc + c.planejado, 0);
const total_realizado = categorias.reduce((acc, c) => acc + c.realizado, 0);

const total_aplicado = Number(investRow.total_aplicado);
const total_resgatado = Number(investRow.total_resgatado);
const total_investido_liquido = Number((total_aplicado - total_resgatado).toFixed(2));

const saldo_livre = Number((total_planejado - total_realizado - total_aplicado + total_resgatado).toFixed(2));

const categorias_estouradas = categorias
  .map(c => {
    let status = null;
    if (c.planejado > 0 && c.realizado > c.planejado) status = 'estourada';
    else if (c.planejado === 0 && c.realizado > 0) status = 'fora_do_planejamento';
    else if (c.planejado > 0 && c.realizado >= c.planejado * 0.9) status = 'no_limite';
    if (!status) return null;
    return { category_id: c.category_id, categoria_nome: c.categoria_nome, emoji: c.emoji, planejado: c.planejado, realizado: c.realizado, excedente: Number((c.realizado - c.planejado).toFixed(2)), status };
  })
  .filter(Boolean);

const texto_categorias = categorias
  .map(c => `${c.emoji} **${c.categoria_nome}**: planejado **R$ ${formatBRL(c.planejado)}**, realizado **R$ ${formatBRL(c.realizado)}**`)
  .join('\n');

let linha_alerta = '';
if (categorias_estouradas.length > 0) {
  const lista = categorias_estouradas.map(c => `**${c.categoria_nome}**`).join(', ');
  linha_alerta = `🚨 Fique de olho em ${lista} - vale a pena conversar com seu planejador sobre isso.`;
}

return [{ json: {
  modo: 'comparativo',
  periodo: { start_date: trigger.start_date, end_date: trigger.end_date },
  total_planejado: Number(total_planejado.toFixed(2)),
  total_realizado: Number(total_realizado.toFixed(2)),
  total_investido_liquido,
  saldo_livre,
  estourou: categorias_estouradas.length > 0 || saldo_livre < 0,
  categorias,
  texto_categorias,
  categorias_estouradas,
  linha_alerta
} }];

